SELECT CASE WHEN c.credit_limit >= 14900 THEN 'high' WHEN c.credit_limit >= 6400 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(s.device))) AS device_values, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(s.country))) AS country_values FROM sessions s LEFT JOIN customers c ON s.customer_id = c.id WHERE c.age < 54 GROUP BY CASE WHEN c.credit_limit >= 14900 THEN 'high' WHEN c.credit_limit >= 6400 THEN 'mid' ELSE 'low' END;
